function layoutCtrl(n,t,i,r,u){"use strict";if(JSON.parse(localStorage.getItem("userData"))===null){location.href="/Login";return}let e=JSON.parse(localStorage.getItem("userData"));n.menus=JSON.parse(localStorage.getItem("menus"));n.subMenus=JSON.parse(localStorage.getItem("subMenus"));n.usuario=e.userName;n.politica=e.role;n.entidad=e.entidad;n.nombreComercial=e.nombreComercial;n.drawMenus=function(){let t="",i=!1;for(let r=0;r<n.menus.length;r++)if(i&&(t+="<\/ul><\/li>",i=!1),n.menus[r].subMenu){i=!0;t+=`<li>
                       <a class="has-arrow waves-effect waves-dark" href="javascript:void(0)" aria-expanded="false"><i class="${n.menus[r].icon}"></i><span class="hide-menu"> ${n.menus[r].description}</span></a>
                       <ul aria-expanded="false" class="collapse">`;for(let i=0;i<n.subMenus.length;i++)n.menus[r].idMenu==n.subMenus[i].idMenu&&(t+='<li><a href="'+n.subMenus[i].url+'">'+n.subMenus[i].description+"<\/a><\/li>")}};const f=r.location.pathname;if(f&&(f==="/"&&(location.href="/Home/Index"),f.indexOf("/Home")==-1)){let t=f.split("/").splice(1).length;if([1,2].includes(t)){let r=f.indexOf("/Index")==-1?f+"/Index":f,t=n.subMenus.find(n=>n.url===r);t&&u.getData("get","/Acceso/GetAccesoBySubMenu?idSubMenu="+t.idSubMenu).then(t=>{if(t.id==="0"&&console.log(t),t.id==="1"){let[r,u,f,e,o]=JSON.parse(t.data);i.usuarioPermiso={almacenPermiso:JSON.parse(u[0].jsonPermission),ventaPermiso:JSON.parse(f[0].jsonPermission),cajaPermiso:JSON.parse(e[0].jsonPermission)};n.accion=r[0];i.articlePermission=o[0];i.ventaPermiso=i.usuarioPermiso.ventaPermiso}})}}n.onChangeSubMenu=function(n){try{console.log(n);location.href=n.url}catch(t){location.href="/Login/Logout"}};n.logout=function(){Object.keys(localStorage).forEach(function(n){localStorage.removeItem(n)});location.href="/Login"}}angular.module("acontPlusApp").controller("layoutCtrl",layoutCtrl);layoutCtrl.$inject=["$scope","$http","$rootScope","$window","mainService","modalService","toastService","formulario"];